__agent_stall_observe_no_progress(
        agent,
        session_id,
        iteration,
        config,
        active_state,
        defer_feedback,
        if to_string(turn_text) != "" {
          turn_text
        } else {
          json_stringify(tool_calls)
        },
        turn_stop_reason,
      )

let warning = __agent_stall_warning_record(
    {
      iteration: iteration,
      tool_name: "",
      args: {},
      signature: tripped.last_diagnostic_signature,
      pattern: pattern,
      count: count,
      consecutive_trips: tripped.consecutive_trips,
      hard_stop: tripped.hard_stop,
      threshold: threshold,
    },
    config,
  )
    + {
      diagnostic_class: tripped.last_diagnostic_class,
      diagnostic_signature: tripped.last_diagnostic_signature,
      diagnostic_snippet: tripped.last_diagnostic_snippet,
    }

next_state = if trip?.advisory_only ?? false {
        // A cumulative observation recurrence is evidence worth surfacing, but
        // never participates in the hard-stop ladder. Interposed activity may
        // be legitimate even when one dead observation keeps recurring.
        __agent_stall_register_recovery(next_state)
      } else {
        __agent_stall_register_trip(next_state, config)
      }
